1	using System.Net.Http.Headers;
2	using System.Text.Json;
3	using System.Text.Json.Nodes;
4	
5	namespace TutorFlow.Api.Llm;
6	
7	public class OpenAiCompatClient(IHttpClientFactory fabrica, IConfiguration cfg) : ILlmClient
8	{
9	    public const string BaseDefecto = "https://generativelanguage.googleapis.com/v1beta/openai";
10	    public const string ModeloDefecto = "gemini-2.5-flash";
11	
12	    public async Task<LlmRespuesta> CompletarAsync(string sistema, IReadOnlyList<LlmMensaje> mensajes,
13	        IReadOnlyList<LlmHerramienta> herramientas, CancellationToken ct)
14	    {
15	        var baseUrl = (string.IsNullOrWhiteSpace(cfg["LLM_BASE_URL"]) ? BaseDefecto : cfg["LLM_BASE_URL"]!).TrimEnd('/');
16	        var modelo = string.IsNullOrWhiteSpace(cfg["LLM_MODEL"]) ? ModeloDefecto : cfg["LLM_MODEL"]!;
17	
18	        var msgs = new JsonArray { new JsonObject { ["role"] = "system", ["content"] = sistema } };
19	        foreach (var m in mensajes)
20	        {
21	            if (m.Rol == "tool")
22	                msgs.Add(new JsonObject { ["role"] = "tool", ["tool_call_id"] = m.ToolCallId, ["content"] = m.Contenido });
23	            else if (m.Rol == "assistant" && m.Llamadas is { Count: > 0 })
24	            {
25	                var calls = new JsonArray();
26	                foreach (var l in m.Llamadas)
27	                    calls.Add(new JsonObject
28	                    {
29	                        ["id"] = l.Id,
30	                        ["type"] = "function",
31	                        ["function"] = new JsonObject { ["name"] = l.Nombre, ["arguments"] = l.ArgumentosJson },
32	                    });
33	                msgs.Add(new JsonObject
34	                {
35	                    ["role"] = "assistant",
36	                    ["content"] = string.IsNullOrEmpty(m.Contenido) ? null : m.Contenido,
37	                    ["tool_calls"] = calls,
38	                });
39	            }
40	            else
41	                msgs.Add(new JsonObject { ["role"] = m.Rol, ["content"] = m.Contenido });
42	        }
43	
44	        var cuerpo = new JsonObject { ["model"] = modelo, ["messages"] = msgs };
45	        if (herramientas.Count > 0)
46	        {
47	            var tools = new JsonArray();
48	            foreach (var h in herramientas)
49	                tools.Add(new JsonObject
50	                {
51	                    ["type"] = "function",
52	                    ["function"] = new JsonObject
53	                    {
54	                        ["name"] = h.Nombre,
55	                        ["description"] = h.Descripcion,
56	                        ["parameters"] = LlmHttp.ParseOVacio(h.ParametrosJsonSchema),
57	                    },
58	                });
59	            cuerpo["tools"] = tools;
60	        }
61	
62	        using var req = new HttpRequestMessage(HttpMethod.Post, $"{baseUrl}/chat/completions");
63	        req.Headers.Authorization = new AuthenticationHeaderValue("Bearer", cfg["LLM_API_KEY"]);
64	        using var doc = await LlmHttp.EnviarAsync(fabrica.CreateClient("llm"), req, cuerpo, ct);
65	
66	        try
67	        {
68	            var raiz = doc.RootElement;
69	            var mensaje = raiz.GetProperty("choices")[0].GetProperty("message");
70	            string? texto = mensaje.TryGetProperty("content", out var c) && c.ValueKind == JsonValueKind.String ? c.GetString() : null;
71	            var llamadas = new List<LlmLlamadaHerramienta>();
72	            if (mensaje.TryGetProperty("tool_calls", out var tc) && tc.ValueKind == JsonValueKind.Array)
73	            {
74	                var n = 0;
75	                foreach (var t in tc.EnumerateArray())
76	                {
77	                    var f = t.GetProperty("function");
78	                    var id = t.TryGetProperty("id", out var i) && i.ValueKind == JsonValueKind.String && !string.IsNullOrEmpty(i.GetString())
79	                        ? i.GetString()! : $"call_{n}";
80	                    var args = f.TryGetProperty("arguments", out var a)
81	                        ? (a.ValueKind == JsonValueKind.String ? a.GetString()! : a.GetRawText()) : "{}";
82	                    llamadas.Add(new(id, f.GetProperty("name").GetString()!, string.IsNullOrWhiteSpace(args) ? "{}" : args));
83	                    n++;
84	                }
85	            }
86	            var uso = raiz.TryGetProperty("usage", out var u) ? u : default;
87	            return new(texto, llamadas, new(LlmHttp.Entero(uso, "prompt_tokens"), LlmHttp.Entero(uso, "completion_tokens")));
88	        }
89	        catch (Exception e) when (e is KeyNotFoundException or InvalidOperationException or IndexOutOfRangeException or ArgumentOutOfRangeException)
90	        {
91	            throw new LlmException("El proveedor del modelo devolvió una respuesta sin los campos esperados.");
92	        }
93	    }
94	}
95

1	using System.Text;
2	using System.Text.Json;
3	using System.Text.Json.Nodes;
4	
5	namespace TutorFlow.Api.Llm;
6	
7	public class AnthropicClient(IHttpClientFactory fabrica, IConfiguration cfg) : ILlmClient
8	{
9	    public const string BaseDefecto = "https://api.anthropic.com";
10	    public const string ModeloDefecto = "claude-haiku-4-5";
11	    const int MaxTokens = 2048;
12	
13	    public async Task<LlmRespuesta> CompletarAsync(string sistema, IReadOnlyList<LlmMensaje> mensajes,
14	        IReadOnlyList<LlmHerramienta> herramientas, CancellationToken ct)
15	    {
16	        var baseUrl = (string.IsNullOrWhiteSpace(cfg["LLM_BASE_URL"]) ? BaseDefecto : cfg["LLM_BASE_URL"]!).TrimEnd('/');
17	        var modelo = string.IsNullOrWhiteSpace(cfg["LLM_MODEL"]) ? ModeloDefecto : cfg["LLM_MODEL"]!;
18	
19	        var msgs = new JsonArray();
20	        JsonArray? resultados = null; // bloques tool_result consecutivos
21	        foreach (var m in mensajes)
22	        {
23	            if (m.Rol == "tool")
24	            {
25	                if (resultados == null)
26	                {
27	                    resultados = [];
28	                    msgs.Add(new JsonObject { ["role"] = "user", ["content"] = resultados });
29	                }
30	                resultados.Add(new JsonObject { ["type"] = "tool_result", ["tool_use_id"] = m.ToolCallId, ["content"] = m.Contenido });
31	                continue;
32	            }
33	            resultados = null;
34	            var bloques = new JsonArray();
35	            if (!string.IsNullOrEmpty(m.Contenido) || m.Llamadas is not { Count: > 0 })
36	                bloques.Add(new JsonObject { ["type"] = "text", ["text"] = m.Contenido });
37	            if (m.Rol == "assistant" && m.Llamadas != null)
38	                foreach (var l in m.Llamadas)
39	                    bloques.Add(new JsonObject
40	                    {
41	                        ["type"] = "tool_use",
42	                        ["id"] = l.Id,
43	                        ["name"] = l.Nombre,
44	                        ["input"] = LlmHttp.ParseOVacio(l.ArgumentosJson),
45	                    });
46	            msgs.Add(new JsonObject { ["role"] = m.Rol == "assistant" ? "assistant" : "user", ["content"] = bloques });
