5	namespace TutorFlow.Api.Llm;
6	
7	// Falla del proveedor. El mensaje nunca incluye llaves, cuerpos ni cabeceras.
8	public class LlmException(string mensaje) : Exception(mensaje);
9	
10	static class LlmHttp
11	{
12	    public static async Task<JsonDocument> EnviarAsync(HttpClient http, HttpRequestMessage req, JsonNode cuerpo, CancellationToken ct)
13	    {
14	        req.Content = new StringContent(cuerpo.ToJsonString(), Encoding.UTF8, "application/json");
15	        try
16	        {
17	            using var resp = await http.SendAsync(req, ct);
18	            if (!resp.IsSuccessStatusCode)
19	                throw new LlmException($"El proveedor del modelo respondió {(int)resp.StatusCode}.");
20	            var texto = await resp.Content.ReadAsStringAsync(ct);
21	            return JsonDocument.Parse(texto);
22	        }
23	        catch (LlmException) { throw; }
24	        catch (OperationCanceledException) when (ct.IsCancellationRequested) { throw; }
25	        catch (OperationCanceledException) { throw new LlmException("El proveedor del modelo no respondió a tiempo."); }
26	        catch (JsonException) { throw new LlmException("El proveedor del modelo devolvió una respuesta no válida."); }
27	        catch (HttpRequestException) { throw new LlmException("No se pudo contactar al proveedor del modelo."); }
28	    }
29	
30	    public static JsonNode ParseOVacio(string json)
31	    {
32	        try { return JsonNode.Parse(json) ?? new JsonObject(); }
33	        catch (JsonException) { return new JsonObject(); }
34	    }
35	
36	    public static int Entero(JsonElement padre, string nombre) =>
37	        padre.ValueKind == JsonValueKind.Object && padre.TryGetProperty(nombre, out var v)
38	        && v.ValueKind == JsonValueKind.Number && v.TryGetInt32(out var n) ? n : 0;
39	}
