7	static string ResolverRuta(string? configurada)
8	{
9	    if (!string.IsNullOrWhiteSpace(configurada)) return Path.GetFullPath(configurada);
10	    foreach (var inicio in new[] { AppContext.BaseDirectory, Directory.GetCurrentDirectory() })
11	        for (var d = new DirectoryInfo(inicio); d != null; d = d.Parent)
12	            if (Directory.Exists(Path.Combine(d.FullName, "data", "api"))) return Path.Combine(d.FullName, "data");
13	    return Path.GetFullPath("data");
14	}
15	
16	var ruta = ResolverRuta(builder.Configuration["Datos:Ruta"]);
17	builder.Services.AddSingleton(_ => new Reglamento(Path.Combine(ruta, "reglamento")));
18	builder.Services.AddSingleton(_ => new Datos(Path.Combine(ruta, "api")));
19	builder.Services.AddHttpClient("llm", c => c.Timeout = TimeSpan.FromSeconds(60));
20	builder.Services.AddSingleton<ILlmClient>(sp =>
21	{
22	    var cfg = sp.GetRequiredService<IConfiguration>();
23	    var proveedor = (cfg["LLM_PROVIDER"] ?? "").Trim();
24	    if (proveedor.Length == 0 || proveedor.Equals("openai", StringComparison.OrdinalIgnoreCase))
25	        return ActivatorUtilities.CreateInstance<OpenAiCompatClient>(sp);
26	    if (proveedor.Equals("anthropic", StringComparison.OrdinalIgnoreCase))
27	        return ActivatorUtilities.CreateInstance<AnthropicClient>(sp);
28	    throw new InvalidOperationException("LLM_PROVIDER no es válido: use 'openai' o 'anthropic'.");
29	});
30	builder.Services.AddSingleton<Asistente>();
31	
32	var app = builder.Build();
33	
34	// Carga eager: un dato corrupto falla al arrancar, nunca convierte un 400 en 500.
35	app.Services.GetRequiredService<Reglamento>();
36	app.Services.GetRequiredService<Datos>();
37	app.Services.GetRequiredService<ILlmClient>();
38	
39	app.MapGet("/api/salud", () => Results.Json(new { estado = "ok" }));
40	
41	app.MapPost("/api/asistente/preguntar", async (HttpRequest req, Datos datos, IConfiguration cfg, Asistente asistente) =>
42	{
43	    static IResult Error(int codigo, string msg) => Results.Json(new { error = msg }, statusCode: codigo);
44	
45	    JsonDocument doc;
46	    try { doc = await JsonDocument.ParseAsync(req.Body); }
47	    catch (JsonException) { return Error(400, "El cuerpo no es un JSON válido."); }
48	
49	    using (doc)
50	    {
51	        var raiz = doc.RootElement;
52	        if (raiz.ValueKind != JsonValueKind.Object) return Error(400, "El cuerpo debe ser un objeto JSON.");
53	
54	        if (!raiz.TryGetProperty("pregunta", out var p) || p.ValueKind != JsonValueKind.String
55	            || string.IsNullOrWhiteSpace(p.GetString()))
56	            return Error(400, "La pregunta es obligatoria.");
57	        if (p.GetString()!.Length > 1000) return Error(400, "La pregunta no puede superar 1.000 caracteres.");
58	
59	        if (!raiz.TryGetProperty("usuario", out var u) || u.ValueKind != JsonValueKind.Object)
60	            return Error(400, "El usuario es obligatorio.");
61	        if (!u.TryGetProperty("rol", out var r) || r.ValueKind != JsonValueKind.String)
62	            return Error(400, "El rol es obligatorio.");
63	        var rol = r.GetString()!;
64	        if (rol != "estudiante" && rol != "coordinador")
65	            return Error(400, "El rol debe ser 'estudiante' o 'coordinador'.");
66	        if (!u.TryGetProperty("id", out var i) || i.ValueKind != JsonValueKind.String
67	            || string.IsNullOrWhiteSpace(i.GetString()))
